          ...validPackage(),
          'manifest.json': utf8.encode(commented),
        });
        final res = runGuard(['check', zip.path]);
        expect(res.exitCode, isNot(0));
        expect('${res.stdout}${res.stderr}', contains('manifest-parse'));
      },
    );

