Map<String, dynamic> _manifestJsonMap() {
  for (final path in const [
    'browser_ext/manifest.json', // cwd = repo root (dart test <path>)
    '../manifest.json', // cwd = browser_ext/dart (package root)
  ]) {
    final file = File(path);
    if (file.existsSync()) {
      // The manifest carries // comments (Chrome's parser is lenient,
      // jsonDecode is not) — strip them, same as chrome_driver.dart.
      final raw = file
          .readAsStringSync()
          .replaceAll(RegExp(r'^\s*//.*$', multiLine: true), '');
