        '"manifest_version": 2',
      );
      final zip = writeZip('mv2.zip', {
        ...validPackage(),
        'manifest.json': utf8.encode(mv2),
      });
      final res = runGuard(['check', zip.path]);
      expect(res.exitCode, isNot(0));
