      );
      final res = runGuard(['check', zip.path]);
      expect(res.exitCode, isNot(0));
      expect('${res.stdout}${res.stderr}', contains('icons/icon-128.png'));
    });

    test('non-MV3 root manifest fails (AC4 — CWS shape, MV3 parse)', () {
